import { StatusBarAlignment, StatusBarItem, TextEditor, window } from "vscode";
import { LanguageClient, State } from "vscode-languageclient";

enum Status {
  INIT = 1,
  RUNNING = 2,
  ERROR = 3
}

const statusBarText = "GraphQL";
const statusBarUIElements = {
  [Status.INIT]: {
    icon: "sync",
    color: "white",
    tooltip: "GraphQL language server is initializing"
  },
  [Status.RUNNING]: {
    icon: "plug",
    color: "white",
    tooltip: "GraphQL language server is running"
  },
  [Status.ERROR]: {
    icon: "stop",
    color: "red",
    tooltip: "GraphQL language server has stopped"
  }
};
const statusBarItem = window.createStatusBarItem(StatusBarAlignment.Right, 0);
let extensionStatus: Status = Status.RUNNING;
let serverRunning: boolean = true; // TODO: See comment with client.onNotification("init".....
const statusBarActivationLanguageIds = [
  "graphql",
  "javascript",
  "javascriptreact",
  "typescript",
  "typescriptreact"
];

function initStatusBar(
  statusBarItem: StatusBarItem,
  client: LanguageClient,
  editor: TextEditor | undefined
) {
  extensionStatus = Status.INIT;
  // TODO: Make graphql-language-service-server throw relevant
  // notifications. Currently, it does not throw "init" or "exit"
  // and status bar is hard coded to all greens.
  client.onNotification("init", params => {
    extensionStatus = Status.RUNNING;
    serverRunning = true;
    updateStatusBar(statusBarItem, editor);
  });
  client.onNotification("exit", params => {
    extensionStatus = Status.ERROR;
    serverRunning = false;
    updateStatusBar(statusBarItem, editor);
  });

  client.onDidChangeState(event => {
    if (event.newState === State.Running) {
      extensionStatus = Status.RUNNING;
      serverRunning = true;
    } else {
      extensionStatus = Status.ERROR;
      client.info("The graphql server has stopped running");
      serverRunning = false;
    }
    updateStatusBar(statusBarItem, editor);
  });
  updateStatusBar(statusBarItem, editor);

  window.onDidChangeActiveTextEditor((editor: TextEditor | undefined) => {
    // update the status if the server is running
    updateStatusBar(statusBarItem, editor);
  });
}

function updateStatusBar(
  statusBarItem: StatusBarItem,
  editor: TextEditor | undefined
) {
  extensionStatus = serverRunning ? Status.RUNNING : Status.ERROR;
  const statusUI = statusBarUIElements[extensionStatus];
  statusBarItem.text = `$(${statusUI.icon}) ${statusBarText}`;
  statusBarItem.tooltip = statusUI.tooltip;
  statusBarItem.command = "extension.isDebugging";
  statusBarItem.color = statusUI.color;

  if (
    editor &&
    statusBarActivationLanguageIds.indexOf(editor.document.languageId) > -1
  ) {
    statusBarItem.show();
  } else {
    statusBarItem.hide();
  }
}

export default statusBarItem;
export { statusBarItem, initStatusBar, updateStatusBar };

import { ExtractedTemplateLiteral } from "./source-helper";
import { OperationDefinitionNode } from "graphql";

import ApolloClient from "apollo-client";
import gql from "graphql-tag";
import { createHttpLink } from "apollo-link-http";
import { WebSocketLink } from "apollo-link-ws";
import { InMemoryCache } from "apollo-cache-inmemory";
import * as ws from "ws";

import { GraphQLEndpoint } from "graphql-config";
import { OutputChannel } from "vscode";
import { ApolloLink } from "apollo-link";

export class NetworkHelper {
  private outputChannel: OutputChannel;

  constructor(outputChannel: OutputChannel) {
    this.outputChannel = outputChannel;
  }

  executeOperation({
    endpoint,
    literal,
    variables,
    updateCallback
  }: ExecuteOperationOptions) {
    const operation = (literal.ast.definitions[0] as OperationDefinitionNode)
      .operation;
    this.outputChannel.appendLine(`NetworkHelper: operation: ${operation}`);
    this.outputChannel.appendLine(`NetworkHelper: endpoint: ${endpoint.url}`);

    const httpLink = createHttpLink({
      uri: endpoint.url,
      headers: endpoint.headers
    });

    const wsEndpointURL = endpoint.url.replace(/^http/, "ws");
    const wsLink = new WebSocketLink({
      uri: wsEndpointURL,
      options: {
        reconnect: true,
        inactivityTimeout: 30000
      },
      webSocketImpl: ws
    });

    const apolloClient = new ApolloClient({
      link: ApolloLink.split(
        () => {
          return operation === "subscription";
        },
        wsLink,
        httpLink
      ),
      cache: new InMemoryCache({
        addTypename: false
      })
    });

    const parsedOperation = gql`
      ${literal.content}
    `;

    if (operation === "subscription") {
      apolloClient
        .subscribe({
          query: parsedOperation,
          variables
        })
        .subscribe({
          next(data: any) {
            updateCallback(formatData(data), operation);
          }
        });
    } else {
      if (operation === "query") {
        apolloClient
          .query({
            query: parsedOperation,
            variables
          })
          .then((data: any) => {
            updateCallback(formatData(data), operation);
          })
          .catch(err => {
            updateCallback(err.toString(), operation);
          });
      } else {
        apolloClient
          .mutate({
            mutation: parsedOperation,
            variables
          })
          .then((data: any) => {
            updateCallback(formatData(data), operation);
          });
      }
    }
  }
}

export interface ExecuteOperationOptions {
  endpoint: GraphQLEndpoint;
  literal: ExtractedTemplateLiteral;
  variables: { [key: string]: string };
  updateCallback: (data: string, operation: string) => void;
}

function formatData({ data, errors }: any) {
  return JSON.stringify({ data, errors }, null, 2);
}

